\set ON_ERROR_STOP on
begin;
set local role service_role;
do $$ declare ws uuid:='00000000-0000-4000-8000-000000000001';p uuid:='00000000-0000-4000-8000-000000000011';a jsonb;b jsonb;job jsonb;
begin
  if public.growth_wa_claim(ws) <> '[]'::jsonb then raise exception 'default must not claim'; end if;
  if (public.growth_wa_enqueue(ws,p)->>'ok')::boolean then raise exception 'missing consent accepted'; end if;
  perform public.growth_wa_event(ws,'{"key":"optin-A","kind":"message","phone":"5491100000001","external_id":"in-A","body":"QUIERO RECIBIR INVITACIONES DE TRATTO POR WHATSAPP"}');
  if not (public.growth_wa_enqueue(ws,p)->>'ok')::boolean then raise exception 'valid enqueue refused'; end if;
  if (public.growth_wa_enqueue(ws,p)->>'ok')::boolean then raise exception 'duplicate enqueue'; end if;
  update public.growth_wa_config set enabled=true,template_approved=true,phone_number_id='123',waba_id='456',template_name='tratto_proveedores_v1',template_body='Prueba ficticia. Respondé BAJA.',daily_limit=1,monthly_budget_usd=0.10,price_ceiling_usd=0.10 where workspace_id=ws;
  if public.growth_wa_claim(ws)<>'[]'::jsonb then raise exception 'no health accepted'; end if;
  perform public.growth_wa_health(ws,'{"id":"123","quality_rating":"YELLOW","code_verification_status":"VERIFIED","whatsapp_business_manager_messaging_limit":"TIER_250"}','{"data":[{"name":"tratto_proveedores_v1","language":"es_AR","category":"MARKETING","status":"APPROVED","components":[{"type":"BODY","text":"Prueba ficticia. Respondé BAJA."}]}]}');
  if public.growth_wa_claim(ws)<>'[]'::jsonb then raise exception 'bad quality accepted'; end if;
  perform public.growth_wa_health(ws,'{"id":"123","quality_rating":"GREEN","code_verification_status":"VERIFIED","whatsapp_business_manager_messaging_limit":"TIER_250"}','{"data":[{"name":"tratto_proveedores_v1","language":"es_AR","category":"MARKETING","status":"APPROVED","components":[{"type":"BODY","text":"Prueba ficticia. Respondé BAJA."}]}]}');
  a:=public.growth_wa_claim(ws);if jsonb_array_length(a)<>1 then raise exception 'expected single reservation'; end if;
  b:=public.growth_wa_claim(ws);if b<>'[]'::jsonb then raise exception 'over daily or budget cap'; end if;
  if (public.growth_wa_begin((a->0->>'id')::uuid,gen_random_uuid())->>'ok')::boolean then raise exception 'wrong token accepted'; end if;
  job:=public.growth_wa_begin((a->0->>'id')::uuid,(a->0->>'claim_token')::uuid);
  if not (job->>'ok')::boolean then raise exception 'valid begin failed'; end if;
  if (public.growth_wa_begin((a->0->>'id')::uuid,(a->0->>'claim_token')::uuid)->>'ok')::boolean then raise exception 'duplicate dispatch'; end if;
  perform public.growth_wa_result((a->0->>'id')::uuid,(a->0->>'claim_token')::uuid,200,'{"messages":[{"id":"wamid.test-A"}]}');
  perform public.growth_wa_result((a->0->>'id')::uuid,(a->0->>'claim_token')::uuid,200,'{"messages":[{"id":"wamid.test-A"}]}');
  if (select count(*) from public.growth_messages where direction='out')<>1 then raise exception 'duplicate CRM message'; end if;
  if (select state from public.growth_wa_queue where prospect_id=p)<>'accepted' then raise exception 'acceptance confused with delivery'; end if;
  perform public.growth_wa_event(ws,'{"key":"read-A","kind":"status","external_id":"wamid.test-A","status":"read"}');
  perform public.growth_wa_event(ws,'{"key":"sent-A","kind":"status","external_id":"wamid.test-A","status":"sent"}');
  if (select state from public.growth_wa_queue where prospect_id=p)<>'read' then raise exception 'late callback regressed state'; end if;
  perform public.growth_wa_event(ws,'{"key":"read-A","kind":"status","external_id":"wamid.test-A","status":"read"}');
  if (select count(*) from public.growth_wa_events where event_key='read-A')<>1 then raise exception 'duplicate webhook'; end if;
  perform public.growth_wa_event(ws,'{"key":"optin-B","kind":"message","phone":"5491100000002","body":"QUIERO RECIBIR INVITACIONES DE TRATTO POR WHATSAPP"}');
  update public.growth_prospects set datos='{"prospeccion":{"gmail_thread":"old-email"}}' where phone='5491100000002';
  if (public.growth_wa_enqueue(ws,'00000000-0000-4000-8000-000000000012')->>'ok')::boolean then raise exception 'Gmail overlap'; end if;
  update public.growth_prospects set datos='{}',status='registered' where phone='5491100000002';
  if (public.growth_wa_enqueue(ws,'00000000-0000-4000-8000-000000000012')->>'ok')::boolean then raise exception 'registered contacted'; end if;
  perform public.growth_wa_event(ws,'{"key":"optin-C","kind":"message","phone":"5491100000003","body":"QUIERO RECIBIR INVITACIONES DE TRATTO POR WHATSAPP"}');
  perform public.growth_wa_enqueue(ws,'00000000-0000-4000-8000-000000000013');
  perform public.growth_wa_event(ws,'{"key":"baja-C","kind":"message","phone":"5491100000003","body":"BAJA"}');
  if (select state from public.growth_wa_queue where phone='5491100000003')<>'cancelled' then raise exception 'opt-out not cancelled'; end if;
  if not public.growth_wa_suppressed('00000000-0000-4000-8000-000000000002',p,'5491100000001') then raise exception 'workspace crossover'; end if;
  if has_function_privilege('anon','public.growth_wa_claim(uuid,integer)','EXECUTE') or has_function_privilege('authenticated','public.growth_wa_event(uuid,jsonb)','EXECUTE') then raise exception 'public privileged RPC'; end if;
  raise notice 'PASS: default off, consent, quality, budget, daily cap, duplicate reservation/send/webhook, token, statuses, Gmail exclusion, registered, opt-out, workspace, RPC permissions';
end $$;
rollback;
